","/* ============================================================
 Champion Intelligence — Design System
 Deep-navy futuristic intelligence command center
 ============================================================ */

:root {
 /* ---- Base surfaces (deep navy, layered) ---- */
 --ci-bg-0: #060b18; /* app background, deepest */
 --ci-bg-1: #0a1120; /* panel base */
 --ci-bg-2: #0f1930; /* raised card */
 --ci-bg-3: #16233f; /* hover / elevated */
 --ci-glass: rgba(20, 33, 61, 0.55);
 --ci-glass-strong: rgba(24, 40, 74, 0.72);

 /* ---- Borders & lines ---- */
 --ci-border: rgba(120, 160, 220, 0.12);
 --ci-border-strong: rgba(130, 180, 240, 0.24);
 --ci-grid-line: rgba(120, 160, 220, 0.08);

 /* ---- Accents ---- */
 --ci-cyan: #35e0ff; /* informational / primary accent */
 --ci-cyan-soft: rgba(53, 224, 255, 0.14);
 --ci-blue: #4d8dff;
 --ci-violet: #9a7bff;
 --ci-teal: #2fe6c4;

 /* ---- Semantic states ---- */
 --ci-green: #34e3a4; /* healthy */
 --ci-green-soft: rgba(52, 227, 164, 0.14);
 --ci-amber: #ffc24b; /* attention */
 --ci-amber-soft: rgba(255, 194, 75, 0.14);
 --ci-red: #ff5d73; /* critical only */
 --ci-red-soft: rgba(255, 93, 115, 0.14);

 /* ---- Typography ---- */
 --ci-text: #eaf1ff; /* primary white text */
 --ci-text-dim: #9fb2d4; /* secondary */
 --ci-text-faint: #64769a; /* tertiary / labels */
 --ci-font: "Inter", "SF Pro Display", -apple-system, BlinkMacSystemFont,
 "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
 --ci-mono: "SFMono-Regular", "JetBrains Mono", Menlo, Consolas, monospace;

 /* ---- Radius / shadow ---- */
 --ci-radius-sm: 8px;
 --ci-radius: 14px;
 --ci-radius-lg: 20px;
 --ci-shadow: 0 8px 30px rgba(0, 0, 0, 0.45);
 --ci-shadow-soft: 0 4px 18px rgba(0, 0, 0, 0.30);
 --ci-glow-cyan: 0 0 0 1px rgba(53, 224, 255, 0.35), 0 0 22px rgba(53, 224, 255, 0.18);

 /* ---- Gradients ---- */
 --ci-grad-cyan: linear-gradient(135deg, #35e0ff 0%, #4d8dff 100%);
 --ci-grad-violet: linear-gradient(135deg, #9a7bff 0%, #4d8dff 100%);
 --ci-grad-panel: linear-gradient(160deg, rgba(24, 40, 74, 0.65) 0%, rgba(12, 20, 38, 0.65) 100%);

 --ci-sidebar-w: 232px;
 --ci-filter-h: 56px;
 --ci-topbar-h: 60px;
}

* { box-sizing: border-box; }

html, body, #root {
 height: 100%;
 margin: 0;
 padding: 0;
}

body {
 font-family: var(--ci-font);
 color: var(--ci-text);
 background: var(--ci-bg-0);
 -webkit-font-smoothing: antialiased;
 text-rendering: optimizeLegibility;
}

/* Ambient background: subtle radial glows over deep navy */
.ci-app {
 min-height: 100%;
 background:
 radial-gradient(1100px 620px at 78% -8%, rgba(53, 224, 255, 0.10), transparent 60%),
 radial-gradient(900px 560px at 8% 108%, rgba(154, 123, 255, 0.10), transparent 60%),
 var(--ci-bg-0);
 color: var(--ci-text);
}

/* ---- Scrollbars ---- */
*::-webkit-scrollbar { width: 10px; height: 10px; }
*::-webkit-scrollbar-track { background: transparent; }
*::-webkit-scrollbar-thumb {
 background: rgba(120, 160, 220, 0.18);
 border-radius: 8px;
 border: 2px solid transparent;
 background-clip: content-box;
}
*::-webkit-scrollbar-thumb:hover { background: rgba(120, 160, 220, 0.32); background-clip: content-box; }

/* ============================================================
 Surfaces
 ============================================================ */
.ci-panel {
 position: relative;
 background: var(--ci-grad-panel);
 border: 1px solid var(--ci-border);
 border-radius: var(--ci-radius);
 box-shadow: var(--ci-shadow-soft);
 backdrop-filter: blur(14px) saturate(120%);
 -webkit-backdrop-filter: blur(14px) saturate(120%);
 transition: border-color 0.22s ease, transform 0.22s ease, box-shadow 0.22s ease;
}
.ci-panel--hover:hover {
 border-color: var(--ci-border-strong);
 transform: translateY(-2px);
 box-shadow: var(--ci-shadow);
}

.ci-panel__head {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 10px;
 padding: 14px 16px 10px;
}
.ci-panel__title {
 font-size: 13px;
 font-weight: 600;
 letter-spacing: 0.02em;
 color: var(--ci-text);
 margin: 0;
 display: flex;
 align-items: center;
 gap: 8px;
}
.ci-panel__sub {
 font-size: 11px;
 color: var(--ci-text-faint);
 margin: 2px 0 0;
}
.ci-panel__body { padding: 4px 16px 16px; }

/* ---- Section eyebrow / titles ---- */
.ci-eyebrow {
 font-size: 10.5px;
 font-weight: 700;
 letter-spacing: 0.16em;
 text-transform: uppercase;
 color: var(--ci-text-faint);
}

/* ============================================================
 Utility text + chips
 ============================================================ */
.ci-num { font-variant-numeric: tabular-nums; }
.ci-dim { color: var(--ci-text-dim); }
.ci-faint { color: var(--ci-text-faint); }

.ci-chip {
 display: inline-flex;
 align-items: center;
 gap: 5px;
 padding: 3px 9px;
 border-radius: 999px;
 font-size: 11px;
 font-weight: 600;
 line-height: 1;
 border: 1px solid transparent;
 white-space: nowrap;
}
.ci-chip--cyan { color: var(--ci-cyan); background: var(--ci-cyan-soft); border-color: rgba(53,224,255,0.30); }
.ci-chip--green { color: var(--ci-green); background: var(--ci-green-soft); border-color: rgba(52,227,164,0.30); }
.ci-chip--amber { color: var(--ci-amber); background: var(--ci-amber-soft); border-color: rgba(255,194,75,0.30); }
.ci-chip--red { color: var(--ci-red); background: var(--ci-red-soft); border-color: rgba(255,93,115,0.30); }
.ci-chip--ghost { color: var(--ci-text-dim); background: rgba(120,160,220,0.08); border-color: var(--ci-border); }

/* ---- Status dot ---- */
.ci-dot { width: 8px; height: 8px; border-radius: 50%; display: inline-block; position: relative; }
.ci-dot--green { background: var(--ci-green); box-shadow: 0 0 8px var(--ci-green); }
.ci-dot--amber { background: var(--ci-amber); box-shadow: 0 0 8px var(--ci-amber); }
.ci-dot--red { background: var(--ci-red); box-shadow: 0 0 8px var(--ci-red); }
.ci-dot--cyan { background: var(--ci-cyan); box-shadow: 0 0 8px var(--ci-cyan); }
.ci-dot--live::after {
 content: ""; position: absolute; inset: -4px; border-radius: 50%;
 border: 1px solid currentColor; opacity: 0.6; animation: ci-pulse 1.8s ease-out infinite;
}
@keyframes ci-pulse {
 0% { transform: scale(0.7); opacity: 0.7; }
 100% { transform: scale(1.9); opacity: 0; }
}

/* ---- Trend indicators ---- */
.ci-trend { display: inline-flex; align-items: center; gap: 3px; font-size: 12px; font-weight: 600; }
.ci-trend--up { color: var(--ci-green); }
.ci-trend--down { color: var(--ci-red); }
.ci-trend--flat { color: var(--ci-text-faint); }

/* ============================================================
 Grid helpers (12-col)
 ============================================================ */
.ci-grid { display: grid; grid-template-columns: repeat(12, 1fr); gap: 14px; }
.ci-span-2 { grid-column: span 2; }
.ci-span-3 { grid-column: span 3; }
.ci-span-4 { grid-column: span 4; }
.ci-span-5 { grid-column: span 5; }
.ci-span-6 { grid-column: span 6; }
.ci-span-7 { grid-column: span 7; }
.ci-span-8 { grid-column: span 8; }
.ci-span-9 { grid-column: span 9; }
.ci-span-12 { grid-column: span 12; }

@media (max-width: 1240px) {
 .ci-span-2, .ci-span-3 { grid-column: span 4; }
 .ci-span-4, .ci-span-5 { grid-column: span 6; }
 .ci-span-7, .ci-span-8, .ci-span-9 { grid-column: span 12; }
}
@media (max-width: 820px) {
 .ci-grid { grid-template-columns: repeat(4, 1fr); }
 [class*="ci-span-"] { grid-column: span 4; }
}

/* ---- Skeleton loading ---- */
.ci-skel {
 border-radius: var(--ci-radius-sm);
 background: linear-gradient(90deg, rgba(120,160,220,0.06) 25%, rgba(120,160,220,0.14) 37%, rgba(120,160,220,0.06) 63%);
 background-size: 400% 100%;
 animation: ci-shimmer 1.4s ease infinite;
}
@keyframes ci-shimmer { 0% { background-position: 100% 0; } 100% { background-position: -100% 0; } }

/* ---- Fade-in for views ---- */
.ci-fade { animation: ci-fade-in 0.4s ease both; }
@keyframes ci-fade-in { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }

/* ---- Focus visibility for a11y ---- */
:focus-visible { outline: 2px solid var(--ci-cyan); outline-offset: 2px; border-radius: 4px; }
","/* ============================================================
 Champion Intelligence — App Shell
 ============================================================ */

.ci-shell {
 display: grid;
 grid-template-columns: var(--ci-sidebar-w) 1fr;
 min-height: 100vh;
}

/* ---------------- Sidebar ---------------- */
.ci-sidebar {
 position: sticky;
 top: 0;
 height: 100vh;
 display: flex;
 flex-direction: column;
 gap: 4px;
 padding: 18px 12px;
 background: linear-gradient(180deg, rgba(10, 18, 34, 0.92), rgba(6, 11, 24, 0.92));
 border-right: 1px solid var(--ci-border);
 backdrop-filter: blur(12px);
 -webkit-backdrop-filter: blur(12px);
 overflow-y: auto;
 z-index: 30;
}
.ci-brand {
 display: flex;
 align-items: center;
 gap: 10px;
 padding: 6px 8px 16px;
}
.ci-brand__mark {
 width: 34px; height: 34px; flex: none;
 border-radius: 10px;
 background: var(--ci-grad-cyan);
 display: grid; place-items: center;
 box-shadow: 0 0 16px rgba(53, 224, 255, 0.4);
}
.ci-brand__mark svg { width: 20px; height: 20px; }
.ci-brand__name { font-size: 14px; font-weight: 700; letter-spacing: 0.01em; line-height: 1.1; }
.ci-brand__tag { font-size: 10px; color: var(--ci-cyan); letter-spacing: 0.14em; text-transform: uppercase; }

.ci-nav__group { font-size: 10px; letter-spacing: 0.16em; text-transform: uppercase; color: var(--ci-text-faint); padding: 14px 10px 6px; }

.ci-nav__item {
 display: flex;
 align-items: center;
 gap: 11px;
 width: 100%;
 padding: 9px 11px;
 border: none;
 background: transparent;
 color: var(--ci-text-dim);
 font-family: inherit;
 font-size: 13px;
 font-weight: 500;
 border-radius: 10px;
 cursor: pointer;
 text-align: left;
 position: relative;
 transition: background 0.16s ease, color 0.16s ease;
}
.ci-nav__item svg { width: 17px; height: 17px; flex: none; opacity: 0.85; }
.ci-nav__item:hover { background: rgba(120, 160, 220, 0.08); color: var(--ci-text); }
.ci-nav__item--active {
 background: linear-gradient(90deg, rgba(53,224,255,0.16), rgba(53,224,255,0.03));
 color: #fff;
}
.ci-nav__item--active::before {
 content: ""; position: absolute; left: 0; top: 8px; bottom: 8px; width: 3px;
 border-radius: 0 3px 3px 0; background: var(--ci-cyan); box-shadow: 0 0 10px var(--ci-cyan);
}
.ci-nav__item--active svg { opacity: 1; color: var(--ci-cyan); }
.ci-nav__badge {
 margin-left: auto; font-size: 10px; font-weight: 700;
 background: var(--ci-red); color: #fff; border-radius: 999px;
 padding: 1px 6px; line-height: 1.4;
}
.ci-sidebar__footer { margin-top: auto; padding: 12px 10px 4px; border-top: 1px solid var(--ci-border); }
.ci-sidebar__status { display: flex; align-items: center; gap: 8px; font-size: 11px; color: var(--ci-text-faint); }

/* ---------------- Main column ---------------- */
.ci-main { display: flex; flex-direction: column; min-width: 0; }

/* Top bar */
.ci-topbar {
 height: var(--ci-topbar-h);
 display: flex;
 align-items: center;
 gap: 16px;
 padding: 0 22px;
 border-bottom: 1px solid var(--ci-border);
 background: rgba(8, 14, 28, 0.6);
 backdrop-filter: blur(10px);
 position: sticky; top: 0; z-index: 25;
}
.ci-topbar__title { font-size: 17px; font-weight: 700; letter-spacing: 0.01em; }
.ci-topbar__crumb { font-size: 11px; color: var(--ci-text-faint); }
.ci-topbar__spacer { flex: 1; }
.ci-search {
 display: flex; align-items: center; gap: 8px;
 background: rgba(120,160,220,0.07); border: 1px solid var(--ci-border);
 border-radius: 999px; padding: 7px 14px; min-width: 260px; color: var(--ci-text-faint);
 font-size: 12.5px; transition: border-color 0.18s ease;
}
.ci-search:focus-within { border-color: var(--ci-border-strong); }
.ci-search input {
 background: transparent; border: none; outline: none; color: var(--ci-text);
 font-family: inherit; font-size: 12.5px; width: 100%;
}
.ci-topbar__icon {
 width: 36px; height: 36px; display: grid; place-items: center; border-radius: 10px;
 border: 1px solid var(--ci-border); background: rgba(120,160,220,0.05);
 color: var(--ci-text-dim); cursor: pointer; position: relative; transition: all 0.16s ease;
}
.ci-topbar__icon:hover { color: var(--ci-text); border-color: var(--ci-border-strong); }
.ci-topbar__icon .ci-dot { position: absolute; top: 7px; right: 8px; }
.ci-avatar {
 width: 36px; height: 36px; border-radius: 50%;
 background: var(--ci-grad-violet); display: grid; place-items: center;
 font-size: 12px; font-weight: 700; color: #fff; cursor: pointer;
}

/* Filter bar (sticky, contextual) */
.ci-filterbar {
 position: sticky; top: var(--ci-topbar-h); z-index: 22;
 display: flex; align-items: center; gap: 10px; flex-wrap: wrap;
 padding: 10px 22px;
 background: rgba(9, 16, 31, 0.82);
 border-bottom: 1px solid var(--ci-border);
 backdrop-filter: blur(12px);
}
.ci-filterbar__label { display: flex; align-items: center; gap: 6px; font-size: 11px; color: var(--ci-text-faint); margin-right: 2px; }

.ci-content { padding: 18px 22px 40px; }

/* Page header inside content */
.ci-pagehead { display: flex; align-items: flex-end; justify-content: space-between; gap: 16px; margin-bottom: 16px; flex-wrap: wrap; }
.ci-pagehead__title { font-size: 20px; font-weight: 700; margin: 0; }
.ci-pagehead__desc { font-size: 12.5px; color: var(--ci-text-dim); margin: 4px 0 0; max-width: 640px; }
.ci-pagehead__actions { display: flex; gap: 8px; align-items: center; }

@media (max-width: 980px) {
 .ci-shell { grid-template-columns: 1fr; }
 .ci-sidebar { position: fixed; left: -260px; transition: left 0.2s ease; }
 .ci-sidebar--open { left: 0; }
}
","/* ============================================================
 Champion Intelligence — Components
 ============================================================ */

/* ---------------- KPI Card ---------------- */
.ci-kpi {
 display: flex; flex-direction: column; gap: 8px;
 padding: 14px 15px; min-height: 118px; cursor: pointer;
}
.ci-kpi__top { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.ci-kpi__label { font-size: 11.5px; color: var(--ci-text-dim); font-weight: 500; letter-spacing: 0.01em; }
.ci-kpi__icon { width: 30px; height: 30px; border-radius: 9px; display: grid; place-items: center; background: var(--ci-cyan-soft); color: var(--ci-cyan); }
.ci-kpi__icon svg { width: 16px; height: 16px; }
.ci-kpi__value { font-size: 27px; font-weight: 700; line-height: 1; letter-spacing: -0.01em; }
.ci-kpi__unit { font-size: 13px; font-weight: 600; color: var(--ci-text-dim); margin-left: 3px; }
.ci-kpi__foot { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-top: auto; }
.ci-kpi__bench { font-size: 10.5px; color: var(--ci-text-faint); }
.ci-kpi__spark { height: 30px; margin: 0 -2px; }
.ci-kpi__drill {
 position: absolute; top: 12px; right: 12px; opacity: 0; transition: opacity 0.18s ease;
 color: var(--ci-text-faint);
}
.ci-kpi:hover .ci-kpi__drill { opacity: 1; }

/* ---------------- Generic chart wrap ---------------- */
.ci-chart { width: 100%; display: block; }
.ci-chart text { fill: var(--ci-text-faint); font-size: 10px; font-family: var(--ci-font); }
.ci-legend { display: flex; flex-wrap: wrap; gap: 6px 14px; margin-top: 10px; }
.ci-legend__item { display: inline-flex; align-items: center; gap: 6px; font-size: 11px; color: var(--ci-text-dim); cursor: pointer; user-select: none; transition: opacity 0.15s ease; }
.ci-legend__item--off { opacity: 0.38; }
.ci-legend__swatch { width: 10px; height: 10px; border-radius: 3px; }

/* ---------------- Table ---------------- */
.ci-table { width: 100%; border-collapse: collapse; font-size: 12.5px; }
.ci-table th {
 text-align: left; font-size: 10.5px; text-transform: uppercase; letter-spacing: 0.08em;
 color: var(--ci-text-faint); font-weight: 600; padding: 8px 10px; border-bottom: 1px solid var(--ci-border);
 position: sticky; top: 0;
}
.ci-table td { padding: 9px 10px; border-bottom: 1px solid var(--ci-grid-line); color: var(--ci-text-dim); }
.ci-table tbody tr { transition: background 0.14s ease; cursor: pointer; }
.ci-table tbody tr:hover { background: rgba(120,160,220,0.06); }
.ci-table tbody tr:hover td { color: var(--ci-text); }
.ci-table__name { color: var(--ci-text); font-weight: 600; }

/* athlete avatar + row identity */
.ci-ident { display: flex; align-items: center; gap: 10px; }
.ci-ident__av { width: 30px; height: 30px; border-radius: 9px; flex: none; display: grid; place-items: center; font-size: 11px; font-weight: 700; color: #04121e; }
.ci-ident__meta { line-height: 1.25; }
.ci-ident__sub { font-size: 10.5px; color: var(--ci-text-faint); }

/* mini bar meter inside cells */
.ci-meter { height: 6px; border-radius: 4px; background: rgba(120,160,220,0.12); overflow: hidden; min-width: 60px; }
.ci-meter__fill { height: 100%; border-radius: 4px; }

/* ---------------- Action queue ---------------- */
.ci-actions-list { display: flex; flex-direction: column; gap: 8px; }
.ci-action {
 display: flex; align-items: center; gap: 12px; padding: 11px 12px;
 border-radius: var(--ci-radius-sm); border: 1px solid var(--ci-border);
 background: rgba(120,160,220,0.04); transition: all 0.16s ease;
}
.ci-action:hover { border-color: var(--ci-border-strong); background: rgba(120,160,220,0.08); }
.ci-action__pri { width: 4px; align-self: stretch; border-radius: 3px; flex: none; }
.ci-action__body { flex: 1; min-width: 0; }
.ci-action__title { font-size: 12.5px; font-weight: 600; color: var(--ci-text); }
.ci-action__meta { font-size: 11px; color: var(--ci-text-faint); margin-top: 2px; }

/* ---------------- Buttons ---------------- */
.ci-btn {
 display: inline-flex; align-items: center; gap: 7px; padding: 7px 13px;
 font-family: inherit; font-size: 12px; font-weight: 600; line-height: 1;
 border-radius: 9px; border: 1px solid var(--ci-border-strong);
 background: rgba(120,160,220,0.06); color: var(--ci-text); cursor: pointer;
 transition: all 0.16s ease; white-space: nowrap;
}
.ci-btn svg { width: 14px; height: 14px; }
.ci-btn:hover { background: rgba(120,160,220,0.14); border-color: rgba(130,180,240,0.4); transform: translateY(-1px); }
.ci-btn--primary { background: var(--ci-grad-cyan); border: none; color: #04121e; }
.ci-btn--primary:hover { box-shadow: var(--ci-glow-cyan); }
.ci-btn--ghost { background: transparent; border-color: var(--ci-border); color: var(--ci-text-dim); }
.ci-btn--sm { padding: 5px 9px; font-size: 11px; }

/* ---------------- Filter select (custom) ---------------- */
.ci-filter {
 position: relative; display: inline-flex; align-items: center; gap: 7px;
 padding: 6px 11px; border-radius: 9px; border: 1px solid var(--ci-border);
 background: rgba(120,160,220,0.06); color: var(--ci-text); font-size: 12px; cursor: pointer;
 transition: all 0.15s ease; user-select: none;
}
.ci-filter:hover { border-color: var(--ci-border-strong); }
.ci-filter--active { border-color: rgba(53,224,255,0.5); background: var(--ci-cyan-soft); color: var(--ci-cyan); }
.ci-filter__k { color: var(--ci-text-faint); font-size: 10.5px; text-transform: uppercase; letter-spacing: 0.06em; }
.ci-filter__v { font-weight: 600; }
.ci-filter__chev { opacity: 0.6; }
.ci-filter__menu {
 position: absolute; top: calc(100% + 6px); left: 0; z-index: 60; min-width: 168px;
 background: var(--ci-glass-strong); border: 1px solid var(--ci-border-strong);
 border-radius: 11px; box-shadow: var(--ci-shadow); padding: 5px;
 backdrop-filter: blur(16px); max-height: 300px; overflow-y: auto;
}
.ci-filter__opt {
 display: flex; align-items: center; gap: 8px; padding: 7px 9px; border-radius: 7px;
 font-size: 12.5px; color: var(--ci-text-dim); cursor: pointer;
}
.ci-filter__opt:hover { background: rgba(120,160,220,0.1); color: var(--ci-text); }
.ci-filter__opt--sel { color: var(--ci-cyan); }

/* ---------------- Side drawer ---------------- */
.ci-drawer-overlay {
 position: fixed; inset: 0; z-index: 80; background: rgba(3, 7, 16, 0.55);
 backdrop-filter: blur(3px); animation: ci-fade-in 0.2s ease;
}
.ci-drawer {
 position: fixed; top: 0; right: 0; height: 100vh; width: 460px; max-width: 92vw; z-index: 81;
 background: linear-gradient(180deg, #0c1428, #0a101f);
 border-left: 1px solid var(--ci-border-strong); box-shadow: -20px 0 50px rgba(0,0,0,0.5);
 display: flex; flex-direction: column; animation: ci-slide-in 0.28s cubic-bezier(0.16,1,0.3,1);
}
@keyframes ci-slide-in { from { transform: translateX(40px); opacity: 0; } to { transform: none; opacity: 1; } }
.ci-drawer__head { padding: 18px 20px; border-bottom: 1px solid var(--ci-border); display: flex; align-items: flex-start; gap: 12px; }
.ci-drawer__close {
 margin-left: auto; width: 30px; height: 30px; border-radius: 8px; border: 1px solid var(--ci-border);
 background: transparent; color: var(--ci-text-dim); cursor: pointer; display: grid; place-items: center; flex: none;
}
.ci-drawer__close:hover { color: var(--ci-text); border-color: var(--ci-border-strong); }
.ci-drawer__body { padding: 18px 20px; overflow-y: auto; flex: 1; }
.ci-drawer__foot { padding: 14px 20px; border-top: 1px solid var(--ci-border); display: flex; gap: 8px; }

/* ---------------- Expandable panel ---------------- */
.ci-expand__head { display: flex; align-items: center; gap: 8px; cursor: pointer; }
.ci-expand__chev { transition: transform 0.2s ease; color: var(--ci-text-faint); }
.ci-expand__chev--open { transform: rotate(90deg); }

/* ---------------- Tooltip ---------------- */
.ci-tip { position: relative; }
.ci-tip__pop {
 position: fixed; z-index: 90; pointer-events: none;
 background: var(--ci-glass-strong); border: 1px solid var(--ci-border-strong);
 border-radius: 9px; padding: 8px 11px; font-size: 11.5px; color: var(--ci-text);
 box-shadow: var(--ci-shadow); backdrop-filter: blur(14px); min-width: 120px;
 animation: ci-fade-in 0.12s ease;
}
.ci-tip__pop b { color: #fff; }

/* ---------------- Insight callout ---------------- */
.ci-insight {
 display: flex; gap: 10px; padding: 11px 13px; border-radius: var(--ci-radius-sm);
 background: linear-gradient(120deg, rgba(53,224,255,0.10), rgba(53,224,255,0.02));
 border: 1px solid rgba(53,224,255,0.22);
}
.ci-insight__icon { color: var(--ci-cyan); flex: none; margin-top: 1px; }
.ci-insight__txt { font-size: 12px; color: var(--ci-text); line-height: 1.45; }
.ci-insight__txt b { color: var(--ci-cyan); }

/* ---------------- Segmented control ---------------- */
.ci-seg { display: inline-flex; background: rgba(120,160,220,0.07); border: 1px solid var(--ci-border); border-radius: 9px; padding: 2px; }
.ci-seg__btn { border: none; background: transparent; color: var(--ci-text-dim); font-family: inherit; font-size: 11.5px; font-weight: 600; padding: 5px 11px; border-radius: 7px; cursor: pointer; transition: all 0.14s ease; }
.ci-seg__btn--active { background: var(--ci-cyan-soft); color: var(--ci-cyan); }

/* athlete stat block */
.ci-stat { display: flex; flex-direction: column; gap: 3px; }
.ci-stat__v { font-size: 18px; font-weight: 700; }
.ci-stat__l { font-size: 10.5px; color: var(--ci-text-faint); text-transform: uppercase; letter-spacing: 0.06em; }

.ci-divider { height: 1px; background: var(--ci-border); margin: 14px 0; border: none; }
","import React, { createContext, useContext, useState, useEffect, useCallback } from "react";
import { IconName } from "../components/Icons";

export interface NavItem { id: string; label: string; icon: IconName; badge?: number; group: string; }

export const NAV: NavItem[] = [
 { id: "command", label: "Command Center", icon: "command", group: "Intelligence" },
 { id: "radar", label: "Talent Radar", icon: "radar", group: "Intelligence" },
 { id: "athletes", label: "Athletes", icon: "users", group: "Intelligence" },
 { id: "athlete360", label: "Athlete 360", icon: "user", group: "Intelligence" },
 { id: "performance", label: "Performance Intelligence", icon: "chart", group: "Analytics" },
 { id: "wearables", label: "Wearables", icon: "watch", group: "Analytics" },
 { id: "vision", label: "Computer Vision", icon: "eye", group: "Analytics" },
 { id: "benchmark", label: "Global Benchmark", icon: "globe", group: "Analytics" },
 { id: "journey", label: "Development Journey", icon: "journey", group: "Develop" },
 { id: "actions", label: "Actions", icon: "bolt", group: "Develop", badge: 5 },
 { id: "ai", label: "AI Intelligence", icon: "brain", group: "Develop" },
];

export interface Filters {
 sport: string; region: string; age: string; gender: string; stage: string;
 pathway: string; period: string; level: string; source: string;
}
const DEFAULT_FILTERS: Filters = {
 sport: "All Sports", region: "All Regions", age: "All Ages", gender: "All",
 stage: "All Stages", pathway: "All Pathways", period: "Last 12 mo",
 level: "All Levels", source: "All Sources",
};

interface Ctx {
 view: string; navigate: (v: string, opts?: { id?: string }) => void; detailId: string | null;
 filters: Filters; setFilter: (k: keyof Filters, v: string) => void; resetFilters: () => void; activeFilterCount: number;
 toast: (msg: string) => void; toastMsg: string | null;
}
const AppCtx = createContext<Ctx>(null as any);
export const useApp = () => useContext(AppCtx);

function parseUrl() {
 const p = new URLSearchParams(window.location.search);
 return { view: p.get("view") || "command", id: p.get("id") };
}

export function AppProvider({ children }: { children?: React.ReactNode }) {
 const [{ view, id }, setState] = useState(parseUrl);
 const [filters, setFilters] = useState<Filters>(DEFAULT_FILTERS);
 const [toastMsg, setToastMsg] = useState<string | null>(null);

 useEffect(() => {
 const on = () => setState(parseUrl());
 window.addEventListener("popstate", on);
 return () => window.removeEventListener("popstate", on);
 }, []);

 const navigate = useCallback((v: string, opts?: { id?: string }) => {
 const params = new URLSearchParams({ view: v });
 if (opts?.id) params.set("id", opts.id);
 const path = `${window.location.pathname}?${params}`;
 const title = "Champion Intelligence — " + (NAV.find(n => n.id === v)?.label || v);
 if (window.self !== window.top) {
 (window as any).CustomEvent?.fireTop?.("magellanNavigator.permalink.set", { relativePath: path, title });
 }
 window.history.pushState({}, "", path);
 document.title = title;
 setState({ view: v, id: opts?.id || null });
 }, []);

 const setFilter = useCallback((k: keyof Filters, v: string) => setFilters(f => ({ ...f, [k]: v })), []);
 const resetFilters = useCallback(() => setFilters(DEFAULT_FILTERS), []);
 const activeFilterCount = Object.keys(filters).filter(k => (filters as any)[k] !== (DEFAULT_FILTERS as any)[k]).length;

 const toast = useCallback((msg: string) => {
 setToastMsg(msg);
 window.setTimeout(() => setToastMsg(null), 2600);
 }, []);

 return (
 <AppCtx.Provider value={{ view, navigate, detailId: id, filters, setFilter, resetFilters, activeFilterCount, toast, toastMsg }}>
 {children}
 </AppCtx.Provider>
 );
}
