// ---------- Radial gauge ----------
export function RadialGauge({ value, label, color = "var(--ci-cyan)", size = 120 }:
 { value: number; label: string; color?: string; size?: number }) {
 const r = size / 2 - 10, c = 2 * Math.PI * r, cx = size / 2;
 return (
 <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 6 }}>
 <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
 <circle cx={cx} cy={cx} r={r} fill="none" stroke="rgba(120,160,220,0.12)" strokeWidth="9" />
 <circle cx={cx} cy={cx} r={r} fill="none" stroke={color} strokeWidth="9" strokeLinecap="round"
 strokeDasharray={c} strokeDashoffset={c - (value / 100) * c}
 transform={`rotate(-90 ${cx} ${cx})`} style={{ transition: "stroke-dashoffset .8s ease", filter: `drop-shadow(0 0 6px ${color})` }} />
 <text x={cx} y={cx - 2} textAnchor="middle" fontSize="24" fontWeight="700" fill="var(--ci-text)">{value}</text>
 <text x={cx} y={cx + 16} textAnchor="middle" fontSize="9">/ 100</text>
 </svg>
 <span className="ci-faint" style={{ fontSize: 11 }}>{label}</span>
 </div>
 );
}
