","import React from "react";
import { PipeStage } from "../../data/command";

// Elegant horizontal champion pipeline funnel with conversion necks + leakage flag
export function PipelineFunnel({ stages, leakIndex, selected, onSelect }:
 { stages: PipeStage[]; leakIndex: number; selected: string | null; onSelect: (k: string) => void }) {
 const [tip, setTip] = React.useState<{ x: number; y: number; i: number } | null>(null);
 const max = stages[0].value;
 const h = (v: number) => 16 + 74 * Math.pow(v / max, 0.3);
 const conv = (i: number) => Math.round((stages[i + 1].value / stages[i].value) * 100);
 const prevDelta = [-2, -1, 4, -3, 1, 2]; // fabricated prev-period pt change per neck

 return (
 <div style={{ position: "relative" }}>
 <div className="cc-pipe">
 {stages.map((s, i) => (
 <React.Fragment key={s.key}>
 <div className={`cc-pipe__stage ${selected === s.key ? "cc-pipe__stage--sel" : ""}`}
 onClick={() => onSelect(s.key)} title={`Filter by ${s.label}`}>
 <span className="cc-pipe__val">{s.value >= 1000 ? (s.value / 1000).toFixed(s.value >= 100000 ? 0 : 1) + "k" : s.value}</span>
 <div className="cc-pipe__bararea">
 <div className="cc-pipe__bar" style={{ height: h(s.value),
 background: selected && selected !== s.key ? "linear-gradient(180deg, #35506f, #2a3f5c)" : undefined }} />
 </div>
 <span className="cc-pipe__label">{s.label}</span>
 </div>
 {i < stages.length - 1 && (
 <div className={`cc-pipe__gap ${i === leakIndex ? "cc-pipe__gap--leak" : ""}`}
 onMouseEnter={e => setTip({ x: e.clientX, y: e.clientY, i })}
 onMouseMove={e => setTip({ x: e.clientX, y: e.clientY, i })}
 onMouseLeave={() => setTip(null)}>
 <span className="cc-pipe__conv">{conv(i)}%</span>
 <svg className="cc-pipe__arrow" width="16" height="12" viewBox="0 0 16 12" fill="none"
 stroke="currentColor" strokeWidth="1.6"><path d="M2 6h11M9 2l4 4-4 4" strokeLinecap="round" strokeLinejoin="round" /></svg>
 </div>
 )}
 </React.Fragment>
 ))}
 </div>
 {tip && (
 <div className="ci-tip__pop" style={{ left: tip.x + 12, top: tip.y - 10 }}>
 <b>{stages[tip.i].label} → {stages[tip.i + 1].label}</b><br />
 <span className="ci-faint">Progressing {stages[tip.i + 1].value.toLocaleString()} · Dropping {(stages[tip.i].value - stages[tip.i + 1].value).toLocaleString()}</span><br />
 <span className="ci-faint">Conversion {conv(tip.i)}% · {prevDelta[tip.i] >= 0 ? "+" : ""}{prevDelta[tip.i]}pts vs prev period</span>
 </div>
 )}
 </div>
 );
}
