const FLAG: Record<string, string> = { green: "#34e3a4", amber: "#ffc24b", red: "#ff5d73", cyan: "#35e0ff" };

// Stylized national map: soft country silhouette + graticule + talent-density bubbles.
// Bubble size = discovered athletes; color = conversion health (region flag).
export function TalentMap({ regions, selected, onSelect }:
 { regions: RegionT[]; selected: string | null; onSelect: (k: string) => void }) {
 const [tip, setTip] = React.useState<{ x: number; y: number; r: RegionT } | null>(null);
 const W = 360, H = 300;
 const px = (x: number) => (x / 100) * W, py = (y: number) => (y / 100) * H;
 const maxD = Math.max(...regions.map(r => r.discovered));
 const rad = (d: number) => 7 + 20 * Math.sqrt(d / maxD);
 // decorative silhouette
 const land = "M70,60 C120,20 210,18 250,44 C300,34 330,70 316,120 C338,150 320,210 270,224 C250,270 180,282 140,256 C90,268 44,236 52,186 C24,160 30,96 70,60 Z";
 return (
 <div style={{ position: "relative" }}>
 <svg className="ci-chart" viewBox={`0 0 ${W} ${H}`} onMouseLeave={() => setTip(null)}>
 <defs>
