 {[0.25, 0.5, 0.75].map(g => <line key={"h" + g} x1="0" y1={H * g} x2={W} y2={H * g} stroke="var(--ci-grid-line)" />)}
 {[0.25, 0.5, 0.75].map(g => <line key={"v" + g} x1={W * g} y1="0" x2={W * g} y2={H} stroke="var(--ci-grid-line)" />)}
 {regions.map(r => {
 const sel = selected === r.key, c = FLAG[r.flag];
 return (
 <g key={r.key} style={{ cursor: "pointer" }}
 onMouseMove={e => setTip({ x: e.clientX, y: e.clientY, r })}
 onClick={() => onSelect(r.key)}>
 <circle cx={px(r.x)} cy={py(r.y)} r={rad(r.discovered)} fill={c} fillOpacity={sel ? 0.4 : 0.22}
 stroke={c} strokeWidth={sel ? 2.4 : 1.2} style={{ filter: sel ? `drop-shadow(0 0 8px ${c})` : "none", transition: "all .2s" }} />
 <circle cx={px(r.x)} cy={py(r.y)} r="2.4" fill={c} />
 <text x={px(r.x)} y={py(r.y) - rad(r.discovered) - 3} textAnchor="middle" fontSize="9" fontWeight="600" fill="var(--ci-text)">{r.name}</text>
 </g>
 );
 })}
 </svg>
 <div className="ci-legend" style={{ marginTop: 6 }}>
 <span className="ci-legend__item"><span className="ci-legend__swatch" style={{ background: FLAG.green }} />Healthy conversion</span>
 <span className="ci-legend__item"><span className="ci-legend__swatch" style={{ background: FLAG.amber }} />Below average</span>
 <span className="ci-legend__item"><span className="ci-legend__swatch" style={{ background: FLAG.red }} />At risk</span>
