 </div>
 {tip && (
 <div className="ci-tip__pop" style={{ left: tip.x + 12, top: tip.y - 10 }}>
 <b>{tip.r.name}</b><br />
 <span className="ci-faint">{tip.r.discovered.toLocaleString()} discovered · {tip.r.conversion}% conversion</span><br />
 <span className="ci-faint">{tip.r.highPotential} high-potential · {tip.r.pathways.toLocaleString()} pathways</span>
 </div>
 )}
 </div>
 );
}
","import React from "react";
import { VeloPt } from "../../data/command";

const SPORT_COLOR: Record<string, string> = {
 Athletics: "#35e0ff", Swimming: "#34e3a4", Taekwondo: "#9a7bff", Cycling: "#ffc24b",
 Rowing: "#2fe6c4", Judo: "#4d8dff", default: "#8fa6c8",
};

// Quadrant bubble: X = current performance, Y = rate of improvement, size = confidence
export function VelocityScatter({ points, onSelect }:
 { points: VeloPt[]; onSelect: (p: VeloPt) => void }) {
 const [tip, setTip] = React.useState<{ x: number; y: number; p: VeloPt } | null>(null);
 const w = 560, h = 300, pad = 34;
 const X = (v: number) => pad + (v / 100) * (w - pad * 2);
 const Y = (v: number) => h - pad - (v / 100) * (h - pad * 2);
 const midX = X(50), midY = Y(50);
 return (
 <div style={{ position: "relative" }}>
 <svg className="ci-chart" viewBox={`0 0 ${w} ${h}`} onMouseLeave={() => setTip(null)}>
 {/* emerging / high-growth quadrant highlight (top-left) */}
 <rect x={pad} y={pad} width={midX - pad} height={midY - pad} fill="rgba(53,224,255,0.07)" />
 <rect x={pad} y={pad} width={midX - pad} height={midY - pad} fill="none" stroke="rgba(53,224,255,0.28)" strokeDasharray="4 4" />
 <line x1={midX} y1={pad} x2={midX} y2={h - pad} stroke="var(--ci-grid-line)" />
 <line x1={pad} y1={midY} x2={w - pad} y2={midY} stroke="var(--ci-grid-line)" />
 <line x1={pad} y1={pad} x2={pad} y2={h - pad} stroke="var(--ci-border)" />
 <line x1={pad} y1={h - pad} x2={w - pad} y2={h - pad} stroke="var(--ci-border)" />
 {/* quadrant labels */}
 <text x={pad + 6} y={pad + 14} fill="var(--ci-cyan)" fontSize="9.5" fontWeight="700">EMERGING / HIGH GROWTH</text>
 <text x={w - pad - 6} y={pad + 14} textAnchor="end" fontSize="9.5">HIGH PERF / HIGH GROWTH</text>
 <text x={pad + 6} y={h - pad - 6} fontSize="9.5">DEVELOPMENT REQUIRED</text>
 <text x={w - pad - 6} y={h - pad - 6} textAnchor="end" fontSize="9.5">HIGH PERF / LOW GROWTH</text>
 <text x={w / 2} y={h - 4} textAnchor="middle">Current performance level →</text>
 <text x={12} y={h / 2} textAnchor="middle" transform={`rotate(-90 12 ${h / 2})`}>Rate of improvement →</text>
 {points.map(p => {
 const emerging = p.perf < 50 && p.growth > 50;
 const c = SPORT_COLOR[p.sport] || SPORT_COLOR.default;
 return (
 <circle key={p.id} cx={X(p.perf)} cy={Y(p.growth)} r={4 + (p.conf / 100) * 9}
 fill={c} fillOpacity={emerging ? 0.75 : 0.5} stroke={c} strokeWidth={emerging ? 1.8 : 1}
 style={{ cursor: "pointer", filter: emerging ? `drop-shadow(0 0 5px ${c})` : "none" }}
 onMouseMove={e => setTip({ x: e.clientX, y: e.clientY, p })}
 onClick={() => onSelect(p)} />
 );
 })}
 </svg>
 {tip && (
 <div className="ci-tip__pop" style={{ left: tip.x + 12, top: tip.y - 10 }}>
 <b>{tip.p.name}</b> · {tip.p.sport}<br />
 <span className="ci-faint">Age {tip.p.age} · {tip.p.stage}</span><br />
 <span className="ci-faint">Benchmark P{tip.p.perf} · Improvement {tip.p.growth}%</span>
 </div>
 )}
 </div>
 );
}
