","import React from "react";

// ---------- Layered Sankey-style flow ----------
export function SankeyFlow({ nodes, links, height = 260 }:
 { nodes: string[]; links: { s: number; t: number; v: number }[]; height?: number }) {
 const w = 560, h = height, pad = 8;
 // compute layer per node (longest path from a pure source)
 const layer = nodes.map(() => 0);
 for (let k = 0; k < nodes.length; k++)
 links.forEach(l => { if (layer[l.t] < layer[l.s] + 1) layer[l.t] = layer[l.s] + 1; });
 const maxLayer = Math.max(...layer);
 const byLayer: number[][] = Array.from({ length: maxLayer + 1 }, () => []);
 layer.forEach((L, i) => byLayer[L].push(i));
 const pos = nodes.map(() => ({ x: 0, y: 0, h: 0 }));
 const COLORS = ["#35e0ff", "#4d8dff", "#34e3a4", "#9a7bff", "#2fe6c4", "#ffc24b", "#35e0ff", "#ff8fa3"];
 byLayer.forEach((ids, L) => {
 const total = ids.reduce((s, i) => s + Math.max(nodeVal(i), 6), 0);
 let y = pad;
 ids.forEach(i => {
 const nh = (Math.max(nodeVal(i), 6) / total) * (h - pad * 2) - 8;
 pos[i] = { x: pad + (L / maxLayer) * (w - pad * 2 - 12), y, h: Math.max(nh, 14) };
 y += Math.max(nh, 14) + 10;
 });
 });
 function nodeVal(i: number) {
 const out = links.filter(l => l.s === i).reduce((s, l) => s + l.v, 0);
 const inc = links.filter(l => l.t === i).reduce((s, l) => s + l.v, 0);
 return Math.max(out, inc);
 }
 const srcOff: Record<number, number> = {}, tgtOff: Record<number, number> = {};
 const nw = 11;
 return (
 <svg className="ci-chart" viewBox={`0 0 ${w} ${h}`}>
 {links.map((l, i) => {
 const so = srcOff[l.s] || 0, to = tgtOff[l.t] || 0;
 const sv = pos[l.s], tv = pos[l.t];
 const th = (l.v / nodeVal(l.s)) * sv.h;
 const th2 = (l.v / nodeVal(l.t)) * tv.h;
 const x1 = sv.x + nw, y1 = sv.y + so + th / 2;
 const x2 = tv.x, y2 = tv.y + to + th2 / 2;
 srcOff[l.s] = so + th; tgtOff[l.t] = to + th2;
 const mx = (x1 + x2) / 2;
 return <path key={i} d={`M${x1} ${y1} C${mx} ${y1} ${mx} ${y2} ${x2} ${y2}`}
 fill="none" stroke={COLORS[l.s % COLORS.length]} strokeOpacity="0.28"
 strokeWidth={Math.max(th, 2)} style={{ transition: "stroke-opacity .2s" }}>
 <title>{nodes[l.s]} → {nodes[l.t]}: {l.v}</title>
 </path>;
 })}
 {nodes.map((n, i) => (
 <g key={i}>
 <rect x={pos[i].x} y={pos[i].y} width={nw} height={pos[i].h} rx="3"
 fill={COLORS[i % COLORS.length]} />
 <text x={pos[i].x + (layer[i] === maxLayer ? -6 : nw + 6)} y={pos[i].y + pos[i].h / 2}
 textAnchor={layer[i] === maxLayer ? "end" : "start"} dominantBaseline="middle" fontSize="9.5"
 fill="var(--ci-text-dim)">{n}</text>
 </g>
 ))}
 </svg>
 );
}
","import React from "react";
import { Panel } from "../primitives";
import { Chip } from "../KpiCard";
import { PageHead, Insight } from "../common";
import { Button, ActionRow } from "../Button";
import { BenchmarkBars, Funnel, TrendCurve } from "../charts/basic";
import { RegionMap, Distribution, Trajectory } from "../charts/map";
import { SankeyFlow } from "../charts/flow";
import { useApp } from "../../context/AppContext";
import { BENCHMARKS, REGION_INTENSITY, FUNNEL, FLOW, TRAJECTORY } from "../../data/demo";

export function GlobalBenchmark() {
 const { toast } = useApp();
 const [region, setRegion] = React.useState<string | undefined>();
 return (
 <div className="ci-fade">
 <PageHead title="Global Benchmark" desc="Where the nation stands against the world — by discipline, region and podium standard."
 actions={<Button icon="globe" onClick={() => toast("Country comparison")}>Compare nations</Button>} />
 <div className="ci-grid">
 <Panel span={5} hover title="Discipline Benchmark" sub="vs international podium standard"><BenchmarkBars data={BENCHMARKS} /></Panel>
 <Panel span={4} hover title="Regional Competitiveness" sub="Click to inspect"><RegionMap regions={REGION_INTENSITY} selected={region} onSelect={r => { setRegion(r); toast(`Region · ${r}`); }} /></Panel>
 <Panel span={3} hover title="National Standing"><Distribution marker={78} height={150} />
 <div style={{ marginTop: 8, textAlign: "center" }}><Chip status="amber">Ranked 11th globally</Chip></div></Panel>
 <Panel span={12} hover title="Competitiveness Trend" sub="World ranking index by discipline, 6 seasons">
 <TrendCurve labels={["S1", "S2", "S3", "S4", "S5", "S6"]} series={[
 { name: "Athletics", color: "#35e0ff", data: [62, 65, 70, 68, 74, 80] },
 { name: "Swimming", color: "#34e3a4", data: [50, 55, 58, 66, 72, 78] },
 { name: "Cycling", color: "#9a7bff", data: [70, 68, 66, 69, 71, 73] },
 ]} height={200} />
 </Panel>
 </div>
 </div>
 );
}

export function DevelopmentJourney() {
 const { toast } = useApp();
 return (
 <div className="ci-fade">
 <PageHead title="Development Journey" desc="Trace the multi-year pathway from first identification to podium — where athletes accelerate, stall or transfer."
 actions={<ActionRow actions={["Recommend Development Plan", "Track Outcome"]} onAction={a => toast(a)} />} />
 <div style={{ marginBottom: 14 }}><Insight>Median time from identification to pathway placement is <b>2.4 years</b> — 7 months faster than last cohort, driven by digital assessment.</Insight></div>
 <div className="ci-grid">
 <Panel span={8} hover title="Champion Trajectory Bands" sub="Actual progression vs projected pathway"><Trajectory data={TRAJECTORY} height={230} /></Panel>
 <Panel span={4} hover title="Pathway Funnel" sub="Multi-year conversion"><Funnel stages={FUNNEL} onSelect={() => toast("Stage cohort")} /></Panel>
 <Panel span={12} hover title="Progression Flow" sub="How athletes move between stages and pathways over time"><SankeyFlow nodes={FLOW.nodes} links={FLOW.links} height={240} /></Panel>
 </div>
 </div>
 );
}
","import React from "react";
import { Panel } from "../primitives";
import { Chip } from "../KpiCard";
import { PageHead } from "../common";
import { Button } from "../Button";
import { Icon } from "../Icons";
import { useApp } from "../../context/AppContext";
import { ACTION_QUEUE } from "../../data/demo";

const PRI: Record<string, string> = { green: "var(--ci-green)", amber: "var(--ci-amber)", red: "var(--ci-red)", cyan: "var(--ci-cyan)" };
const LANES = [
 { key: "red", label: "Critical", icon: "alert" as const },
 { key: "amber", label: "Attention", icon: "flag" as const },
 { key: "cyan", label: "Opportunity", icon: "star" as const },
 { key: "green", label: "On Track", icon: "activity" as const },
];
const EXTRA = [
 { id: "a6", title: "Coastal swimming surge — allocate scouting capacity", meta: "+34% identification · resourcing", pri: "cyan", type: "Investigate" },
 { id: "a7", title: "Nadia Petrov — recovery trending down 3 weeks", meta: "Recovery 58% · Cycling · North", pri: "amber", type: "Assign Specialist" },
 { id: "a8", title: "Sofia Andersen — confirm podium pathway placement", meta: "Percentile 96 · Gymnastics", pri: "green", type: "Track Outcome" },
];

export function Actions() {
 const { toast } = useApp();
 const all = [...ACTION_QUEUE, ...EXTRA];
 return (
 <div className="ci-fade">
 <PageHead title="Actions" desc="Every insight connects to a next best action. Prioritized, assignable and tracked to outcome — no passive dashboards."
 actions={<Button icon="plus" variant="primary" onClick={() => toast("New intervention created")}>Create Intervention</Button>} />

 <div className="ci-grid">
 {LANES.map(lane => {
 const items = all.filter(a => a.pri === lane.key);
 const I = Icon[lane.icon];
 return (
 <Panel key={lane.key} span={3} hover title={lane.label}
 right={<span className="ci-chip ci-chip--ghost">{items.length}</span>}>
 <div className="ci-actions-list">
 {items.length === 0 && <div className="ci-faint" style={{ fontSize: 12, padding: "10px 2px" }}>Nothing here — all clear.</div>}
 {items.map(a => (
 <div className="ci-action" key={a.id} style={{ flexDirection: "column", alignItems: "stretch", gap: 8 }}>
 <div style={{ display: "flex", gap: 10 }}>
 <span style={{ color: PRI[lane.key], flex: "none" }}><I style={{ width: 15, height: 15 }} /></span>
 <div className="ci-action__body">
 <div className="ci-action__title" style={{ fontSize: 12 }}>{a.title}</div>
 <div className="ci-action__meta">{a.meta}</div>
 </div>
 </div>
 <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
 <Chip status={a.pri as any}>{a.type}</Chip>
 <Button size="sm" variant="ghost" onClick={() => toast(`${a.type} actioned`)}>Act</Button>
 </div>
 </div>
 ))}
 </div>
 </Panel>
 );
 })}
 </div>
 </div>
 );
}
","import React from "react";
import { Panel } from "../primitives";
import { Chip } from "../KpiCard";
import { PageHead } from "../common";
import { Button } from "../Button";
import { Icon } from "../Icons";
import { useApp } from "../../context/AppContext";
import { AI_INSIGHTS } from "../../data/demo";

const TAG_STATUS: Record<string, any> = { Opportunity: "cyan", "Talent Transfer": "green", Risk: "amber", Performance: "green" };

export function AIIntelligence() {
 const { toast, navigate } = useApp();
 return (
 <div className="ci-fade">
 <PageHead title="AI Intelligence" desc="Continuous machine analysis across the population — surfacing what changed, why it matters, and what to do next."
 actions={<Button icon="brain" variant="primary" onClick={() => toast("Generating fresh intelligence briefing…")}>Generate Briefing</Button>} />

 <div className="ci-grid">
 <Panel span={8} hover title="Intelligence Feed" sub="Ranked by impact and confidence">
 <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
 {AI_INSIGHTS.map((it, i) => (
 <div key={i} className="ci-action" style={{ alignItems: "flex-start" }}>
 <span style={{ color: "var(--ci-cyan)", flex: "none", marginTop: 2 }}><Icon.spark style={{ width: 16, height: 16 }} /></span>
 <div className="ci-action__body">
 <div style={{ display: "flex", gap: 8, alignItems: "center", marginBottom: 4 }}>
 <Chip status={TAG_STATUS[it.tag]}>{it.tag}</Chip>
 <span className="ci-faint" style={{ fontSize: 10.5 }}>confidence {88 - i * 6}%</span>
 </div>
 <div style={{ fontSize: 12.5, color: "var(--ci-text)", lineHeight: 1.5 }}>{it.t}</div>
 </div>
 <Button size="sm" variant="ghost" onClick={() => navigate("actions")}>Act</Button>
 </div>
 ))}
 </div>
 </Panel>

 <div className="ci-span-4" style={{ display: "flex", flexDirection: "column", gap: 14 }}>
 <Panel hover title="Model Confidence" sub="Prediction reliability by domain">
 {[["Talent identification", 91, "green"], ["Injury forecasting", 84, "green"], ["Transfer matching", 77, "amber"], ["Podium projection", 69, "amber"]].map(([l, v, c]: any) => (
 <div key={l} style={{ marginBottom: 10 }}>
 <div style={{ display: "flex", justifyContent: "space-between", fontSize: 11.5, marginBottom: 3 }}>
 <span className="ci-dim">{l}</span><span className="ci-num">{v}%</span>
 </div>
 <div className="ci-meter"><div className="ci-meter__fill" style={{ width: `${v}%`, background: `var(--ci-${c})` }} /></div>
 </div>
 ))}
 </Panel>
 <Panel hover title="Ask Champion IQ" sub="Natural-language intelligence">
 <div className="ci-search" style={{ minWidth: 0, marginBottom: 10 }}>
 <Icon.brain style={{ width: 15, height: 15 }} />
 <input placeholder="e.g. Who should we assess next?" aria-label="Ask AI" />
 </div>
 {["Which regions are under-scouted?", "Who is at risk of dropout?", "Best transfer candidates?"].map(q => (
 <div key={q} className="ci-filter__opt" style={{ borderRadius: 8, marginBottom: 2 }} onClick={() => toast("Analyzing: " + q)}>
 <Icon.search style={{ width: 12, height: 12 }} /> {q}
 </div>
 ))}
 </Panel>
 </div>
 </div>
 </div>
 );
}
","import React from "react";
import "./theme.css";
import "./app.css";
import "./components.css";
import { AppProvider, useApp } from "./context/AppContext";
import { Sidebar } from "./components/shell/Sidebar";
import { TopBar } from "./components/shell/TopBar";
import { FilterBar } from "./components/shell/FilterBar";
import { Toast, AthleteDrawer } from "./components/common";
import { CommandCenter } from "./components/views/CommandCenter";
import { TalentRadar } from "./components/views/TalentRadar";
import { Athletes } from "./components/views/Athletes";
import { Athlete360 } from "./components/views/Athlete360";
import { Performance, Wearables, ComputerVision } from "./components/views/Analytics";
import { GlobalBenchmark, DevelopmentJourney } from "./components/views/BenchJourney";
import { Actions } from "./components/views/Actions";
import { AIIntelligence } from "./components/views/AIIntelligence";
import { Athlete } from "./data/demo";

function Router() {
 const { view } = useApp();
 const [athlete, setAthlete] = React.useState<Athlete | null>(null);
 const pick = (a: Athlete) => setAthlete(a);

 const render = () => {
 switch (view) {
 case "command": return <CommandCenter />;
 case "radar": return <TalentRadar onAthlete={pick} />;
 case "athletes": return <Athletes onAthlete={pick} />;
 case "athlete360": return <Athlete360 />;
 case "performance": return <Performance onAthlete={pick} />;
 case "wearables": return <Wearables onAthlete={pick} />;
 case "vision": return <ComputerVision />;
 case "benchmark": return <GlobalBenchmark />;
 case "journey": return <DevelopmentJourney />;
 case "actions": return <Actions />;
 case "ai": return <AIIntelligence />;
 default: return <CommandCenter />;
 }
 };

 return (
 <div className="ci-shell">
 <Sidebar />
 <div className="ci-main">
 <TopBar />
 <FilterBar />
 <main className="ci-content">{render()}</main>
 </div>
 <AthleteDrawer athlete={athlete} onClose={() => setAthlete(null)} />
 <Toast />
 </div>
 );
}

export default function App() {
 return (
 <AppProvider>
 <div className="ci-app"><Router /></div>
 </AppProvider>
 );
}
